-- Placeholder copy for the hidden pages (developer-managed; replaced when the company supplies final write-ups).
UPDATE qr_page_translations t
SET title = 'Hidden Page ' || p.slot_number || ' (placeholder)',
    body  = 'Placeholder content. The final write-up will be added by the developers.'
FROM qr_pages p
WHERE t.qr_page_id = p.id AND t.language_code = 'en' AND p.slot_number BETWEEN 1 AND 8
  AND (t.title LIKE 'Page % (temporary)' OR t.title LIKE 'Secret Page % (placeholder)');

COMMIT;
